import { Client } from 'pg';

const SQL = `
CREATE TABLE IF NOT EXISTS "items" (
	"item_no" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"quantity_in_stock" INTEGER NOT NULL CHECK(quantity_in_stock >= 0),
	"price" NUMERIC(10,2) NOT NULL CHECK(price > 0),
	"discounted_price" NUMERIC(2,0) CHECK(discounted_price > 0),
	"brand_id" INTEGER NOT NULL,
    "img_url" VARCHAR(255),
    CONSTRAINT valid_discount CHECK (price > discounted_price),
	PRIMARY KEY("item_no")
);

CREATE TABLE IF NOT EXISTS "categories" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "item_categories" (
	"item_id" INTEGER NOT NULL,
	"category_id" INTEGER NOT NULL,
	PRIMARY KEY("item_id", "category_id")
);

CREATE TABLE IF NOT EXISTS "brands" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255),
	PRIMARY KEY("id")
);

ALTER TABLE "item_categories"
ADD FOREIGN KEY("item_id") REFERENCES "items"("item_no")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "item_categories"
ADD FOREIGN KEY("category_id") REFERENCES "categories"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "brands"
ADD FOREIGN KEY("id") REFERENCES "items"("brand_id")
ON UPDATE CASCADE ON DELETE SET NULL;
`;

const dbUrl = process.env.argv[2];

(async () => {
  console.log('seeding...');
  const client = new Client({
    connectionString: dbUrl,
  });
  await client.connect();
  await client.query(SQL);
  await client.end();
  console.log('done');
})();
